{{axiom | n = 3
        | lc= '''[[Definition:Ring Product|Ring Product]]:'''
        | ml= \sequence {r_0, r_1, r_2, \ldots} \odot \sequence {s_0, s_1, s_2, \ldots}
        | mo= =
